import { card, type CardCopy } from './contentTypes';

export const scenarioEnglish: Record<string, CardCopy> = {
'cicd/stages': card('Stages, jobs and needs', 'GitLab pipelines organize validation and delivery through dependencies and trigger rules; make the critical path and failures understandable.', 'Explain critical-path changes, failure categories and feedback time.',
'Stages provide default ordering, while needs expresses dependencies that permit earlier execution. Design artifact transfer alongside execution order, and coordinate pipeline and job rules.\n\nParallelize independent checks and move inexpensive failures earlier. Keep essential verification, bound infrastructure retries, and prevent stale or concurrent deployment jobs from overwriting releases.',
['Design execution dependencies and artifact downloads together.', 'Coordinate merge-request and branch rules to avoid duplicates or omissions.', 'Optimize the measured critical path first.', 'Prevent concurrent or stale deployment jobs from overwriting releases.'],
['Stages alone do not express every data dependency.', 'Do not retry every failure indiscriminately.'],
[['How do needs and stages interact?', "stages provide the default order. needs lets a job start after its declared dependencies finish without waiting for the entire earlier stage. Use needs:artifacts to control downloads from those dependencies. Use needs:optional when rules can omit a dependency and the job can run without it."], ['How should rules be designed?', "Define conditions for merge requests, branches, Git tags and changed files. GitLab evaluates rules in order. The first matching rule determines job inclusion and the applicable attributes. If no rule matches, the job is omitted. Test the major trigger types and exclusion paths."], ['workflow: rules versus job rules?', 'Workflow rules decide whether a pipeline exists; job rules decide which jobs it includes and their attributes. Coordinate them to prevent duplicate pipelines or missing checks.'], ['How is feedback time reduced?', 'Parallelize independent checks, improve caching and optimize the critical path. Put quick checks early and select heavier validation by risk without losing necessary correctness coverage.'], ['Which failures should be retried?', 'Transient network, executor or controlled infrastructure failures may merit bounded retries. Deterministic code, permission and assertion failures should surface directly. Bound total time as well as attempts.']]),
'cicd/templates': card('CI templates and variables', 'Shared CI templates need stable interfaces, useful defaults and explicit extension points.', 'Explain template contracts, upgrade strategy and demonstrated adoption.',
'Keep common behavior in versioned templates with constrained inputs. Define which checks are mandatory and which project-specific behavior may be extended.\n\nInspect the merged configuration rather than assuming inheritance semantics. Roll upgrades through representative projects, measure outcomes and retain a known rollback version.',
['Version shared templates and publish change notes.', 'Constrain input types or allowed values.', 'Mappings and arrays do not necessarily merge the same way.', 'Make the final merged configuration inspectable and testable.'],
['Do not make every project follow an unvalidated template main branch.', 'Unrestricted overrides can disable required checks.'],
[['What if a project needs overrides?', 'Provide explicit extension points and distinguish configurable behavior from mandatory validation. Inspect the merged script, rules and checks for accidental removal.'], ['How should variables be layered?', 'Separate template defaults, project settings, environment settings and secrets, with clear precedence and ownership. Validate critical inputs and keep secrets out of template repositories.'], ['How should template upgrades roll out?', 'Pin versions, trial representative projects, compare success rates, duration and artifacts, then expand gradually. Keep a rollback version rather than updating all delivery chains at once.'], ['What is a common extends mistake?', "extends performs a reverse deep merge by key, with applicable child values or later parents overriding the same key. Arrays are replaced rather than concatenated. For example, a child job’s script replaces the inherited script. Inspect the expanded configuration when inheritance has several layers."], ['How can teams maintain templates together?', 'Define interface ownership, compatibility and change review. Centralize shared capabilities and use limited extension points for exceptions instead of accumulating unlimited switches.']]),
'cicd/quality': card('Caches, artifacts and quality gates', 'Quality gates should verify release-critical behavior and produce actionable failure evidence.', 'Explain risk coverage rather than reporting only tool counts.',
'Use caches for regenerable inputs and artifacts for explicit outputs passed between jobs. Connect tests and scans to the exact artifact being promoted.\n\nCoverage and scanner counts need interpretation. Test boundaries, concurrency and recovery; manage false positives with scoped, expiring exceptions while retaining essential checks.',
['Test business boundaries and recovery paths.', 'Caches are not a reliable artifact-transfer contract.', 'Metrics require definitions and explicit interpretation limits.', 'Exceptions need expiry dates and repair ownership.'],
['A coverage target does not replace critical-path testing.', 'False positives should not disable the entire gate indefinitely.'],
[['What if a cache is corrupted?', 'Jobs must regenerate dependencies after cache loss or clearing. Include lockfiles, toolchains and platforms in keys, and investigate contamination rather than treating old cache contents as authoritative.'], ['How are disputed gate rules handled?', 'Relate rules to actual risk and incident history, comparing false-positive and false-negative costs. Keep exceptions scoped, owned and time-limited without removing core checks.'], ['What if artifacts are too large?', 'Retain only needed deliverables and diagnostics with suitable access and expiry. Store large release artifacts in a registry with digests rather than repeatedly uploading whole workspaces.'], ['Does adequate coverage prove quality?', 'No. Coverage shows executed code, not effective assertions or correct recovery. Verify critical behavior, boundaries, concurrency and failure handling.'], ['How should security scans be integrated?', 'Set thresholds from exploitability, exposure and remediation options. Maintain scanner data and exceptions, bind findings to artifact versions and define a response process.']]),
'cicd/kaniko': card('Container image builders', 'Choose builders by maintenance status, isolation and provenance; describe historical Kaniko use with its maintenance boundaries.', 'Retain accurate historical tool names while explaining maintenance changes and migration evaluation.',
'Assess the builder’s current maintenance, privilege model and compatibility with the target Runner. Lack of privileged mode alone does not establish complete build security.\n\nRecord source revision, builder and dependency versions, image digest and validation results. Promote the same validated artifact, and evaluate alternatives in the actual execution environment.',
['Tool maintenance status changes over time.', 'Rootless operation depends on the kernel and execution environment.', 'Build secrets must not become image layers.', 'Promote the same artifact that was validated.'],
['Do not recommend an archived project as an unquestioned default.', 'Avoid equating non-privileged execution with complete security.'],
[['How does this compare with Docker-in-Docker?', 'Compare daemons, privileges, isolation, caching and platform compatibility. Alternatives such as rootless BuildKit also have environmental requirements; validate on the target Runner.'], ['How is artifact provenance established?', 'Record source SHA, builder and dependency versions, digest, tests and scans. Promote the specific artifact instead of rebuilding a mutable tag into different content.'], ['How should build caches be managed?', 'Separate inputs, platforms and toolchains, restrict writers and set retention. Cache hits do not replace verification, and ordinary caches must not contain secrets.'], ['How are multi-architecture images validated?', 'Build and test each target platform, distinguishing native execution from emulation. A multi-platform manifest does not prove each image runs correctly.'], ['Should failed builds simply be retried?', 'Bound retries for transient pulls or infrastructure failures. Fix Dockerfile, permission and dependency errors; after recovery, verify provenance and integrity rather than citing one successful attempt.']],
{scope:'The original GoogleContainerTools/kaniko repository is archived. This does not establish the maintenance status of similarly named projects or third-party forks.'}),
'cicd/mrpipe': card('Merge-request and branch pipelines', 'Validate the proposed change in its merge context while restricting permissions available to untrusted code.', 'Identify the exact commit and merge context that were tested.',
'A source branch passing checks does not guarantee the combined result with its target will pass. Align merge policies, pipeline types and verified revisions.\n\nStatus badges summarize particular runs, not all current behavior. Restrict fork code, sensitive variables and privileged Runners, and restore a failing main branch promptly with evidence and regression coverage.',
['A successful badge reports a particular configured run.', 'A passing source branch may still fail after merging.', 'Protecting main requires both configuration and verification.', 'Untrusted code must not automatically receive production credentials.'],
['Confirm the tested commit instead of relying only on a status icon.', 'Do not execute arbitrary fork code on privileged Runners.'],
[['How can slow MR pipelines be optimized?', 'Analyze the critical path, caches and independent jobs; choose integration tests by impact. Do not trade away merge-context coverage or permanently skip failing checks.'], ['What does a badge prove?', 'The state of its configured pipeline or job, subject to branch, revision and test scope. It does not prove the current deployment or every feature is healthy.'], ['Why use merged-results pipelines?', "It tests a temporary merge commit that combines the source and target branches, exposing integration failures that separate branch checks can miss. If the branches conflict, GitLab runs a standard merge request pipeline instead. Check project prerequisites and the pipeline type that actually ran."], ['What if main fails?', 'Restore a verifiable main branch, identify the triggering change and impact, then fix or revert. Preserve evidence and add useful regression coverage rather than permanently allowing failure.'], ['What boundaries matter for fork MRs?', 'Restrict secrets, protected resources and executor privileges; review the code that jobs execute. Code acceptance and permission for privileged execution are separate decisions.']]),
'cicd/deploy': card('Repeatable deployment', 'Pin artifacts and configuration, control concurrency and judge completion through runtime results.', 'Connect release inputs, actual deployed versions and acceptance metrics.',
'Promote a validated artifact with controlled environment configuration and record the actual revision. Serialize conflicting changes so a delayed pipeline cannot replace a newer release.\n\nDefine success, failure and rollback criteria before execution. Verify business recovery and data compatibility; successful commands and healthy Pods are only parts of acceptance.',
['Link source, artifact, configuration and environment in release records.', 'Environment locks prevent conflicting concurrent changes.', 'Define explicit runtime acceptance criteria.', 'Rollback requires data-compatibility checks.'],
['Do not rebuild a mutable image name independently in every environment.', 'Successful deployment commands do not prove business recovery.'],
[['What makes deployment repeatable?', 'Pinned image and configuration versions, declarative or idempotent steps, recorded inputs and actual revisions. Version migrations and external dependencies as well as commands.'], ['How should development and production differ?', 'Express resource, address and policy differences in controlled environment configuration while sharing validated artifacts. Inject secrets securely instead of maintaining drifting code copies.'], ['When should releases be automatic or manual?', 'Use risk, reversibility and validation maturity. Manual steps need a concrete decision; automation still needs observation. A human click alone is not quality assurance.'], ['How is a failed release recovered?', 'Stop further changes, determine impact and in-flight operations, then restore compatible artifacts and configuration. Handle migrations and external effects separately and verify business behavior.'], ['How are multiple clusters updated?', 'Roll progressively across failure domains and traffic, recording each cluster’s version and status. Limit simultaneous exposure and assess shared dependencies.']]),
'cicd/canary': card('Canary releases', 'Canaries limit exposure to new versions when traffic can be distinguished, outcomes compared and data kept compatible.', 'Explain samples, thresholds and data compatibility, not only traffic percentages.',
'Allocate traffic through explicit routing or cohorts and compare version-specific errors, latency, saturation and business outcomes. Define thresholds and required evidence before rollout.\n\nLow traffic may require longer observation and synthetic checks. Preserve uncertainty when samples are insufficient, and ensure shared data permits rollback before describing the release as reversible.',
['Replica ratios do not guarantee precise traffic ratios.', 'Low traffic requires sufficient samples or synthetic validation.', 'Metrics must distinguish versions and cohorts.', 'Shared-data changes must be compatible with rollout order.'],
['Average latency alone is insufficient for expanding traffic.', 'Incompatible data changes can make rollback unsafe.'],
[['Canary versus blue-green?', 'Canary progressively allocates traffic; blue-green usually maintains two environments and switches entry. Both require connection, shared-data and rollback planning; costs and risks guide selection.'], ['Do fewer replicas mean proportionally less traffic?', 'Not necessarily. Balancing, sessions and persistent connections affect distribution. Use explicit weights or cohorts and verify actual request counts.'], ['What should a canary measure?', 'Compare version-specific error rates, tail latency, saturation and key business success rates, with logs and dependencies. Set thresholds and sample requirements in advance.'], ['When should rollback happen?', 'Stop expansion and revert on predefined failure conditions or serious unknown risk. Retain the triggering evidence and confirm database, message and configuration compatibility.'], ['How is low-traffic validation handled?', 'Extend observation and use synthetic requests, shadow traffic or selected users without unintended real effects. Zero errors in an inadequate sample is not proof of safety.']]),
'cicd/supply': card('Software supply-chain checks', 'Protect sources, dependencies, build environments and artifact verification with traceable evidence.', 'Distinguish provenance, vulnerability findings and runtime safety.',
'Constrain build identities and isolate execution, then record dependencies, provenance and artifact digests. Verify signatures against explicit trusted identities and policies.\n\nScanning has detection limits. Maintain findings, remediation and expiring exceptions, and promote the same verified artifact through environments rather than assuming signatures prove correctness.',
['Signature verification requires trusted identities and policies.', 'Scanning depends on vulnerability data and detection capabilities.', 'Minimize credential scope and lifetime.', 'Preserve the same digest through artifact promotion.'],
['A valid signature does not mean vulnerability-free software.', 'Avoid long-lived shared high-privilege build environments.'],
[['How are false positives handled?', 'Record the finding, affected path and evidence that it is inapplicable or unexploitable, with scoped expiry and review. Do not disable whole scan categories or dismiss risk without evidence.'], ['What about emergency exceptions?', 'Limit scope, document risk, ownership and repair deadlines, and retain essential verification and rollback. Urgency does not remove provenance or access controls.'], ['How are base images governed?', 'Use maintained sources, pin versions or digests, update regularly and test compatibility. Minimal size does not replace runtime dependencies, certificates or patchability.'], ['What does signing prove?', 'Under a valid trust policy, it supports artifact integrity and association with a signer or source. It does not prove business correctness or replace scanning and runtime checks.'], ['How are Runners hardened?', 'Separate trusted and untrusted jobs, restrict privileges, host mounts and networking, use short-lived credentials and clean workspaces. Protect caches and outputs against contamination.']]),
'cicd/runners': card('Runner labels and capacity', 'Plan Runner capacity around queueing, job resources and isolation without exceeding dependency or cost limits.', 'Explain queueing, execution cost and trust boundaries.',
'Inspect queue wait and execution time by job class, then distinguish insufficient instances from label mismatch, quotas and startup failures. Configure per-job resources alongside concurrency.\n\nUse isolated environments and protected execution for sensitive work. Improve caches and remove duplicate work before increasing concurrency beyond registry, network or downstream capacity.',
['Tags match jobs to Runners; they are not a complete security boundary.', 'Set concurrency and per-job resource limits together.', 'Ephemeral environments reduce residual state.', 'Include failed retries and queue impact in cost analysis.'],
['Do not give every job shared host privileges for speed.', 'More concurrency can exceed external dependency capacity.'],
[['Which metrics guide scaling?', "Track queue wait, job duration, concurrency utilization, startup failures and saturation by job type. Runner tag mismatches or quotas can leave jobs queued even when instances are idle."], ['How should tags be designed?', 'Group by environment, capability and necessary isolation without excessive fragmentation. Sensitive tasks also require protected configuration and access controls.'], ['What risks do shared Runners create?', 'Untrusted jobs may read residual files or credentials and poison caches. Isolate execution, minimize privileges, clean state and separate trust domains.'], ['How can caches remain safe and useful?', 'Scope keys and permissions by project, lockfiles, platform and trust domain. Rebuild correctly when missing; do not use untrusted caches for privileged releases.'], ['How can CI costs fall?', 'Remove duplicate pipelines and wasteful retries, optimize critical paths, caches and job sizing, then reclaim elastic capacity. Evaluate feedback time and reliability alongside price.']]),
'monitor/golden': card('Troubleshooting with golden signals', 'Latency, traffic, errors and saturation describe service behavior together with user impact and dependencies.', 'Trace evidence from user symptoms to resources and dependencies.',
'Confirm the affected user operations, then correlate latency, errors, traffic and saturation over a shared timeline. Separate successful and failed request latency so fast failures do not hide degradation.\n\nUse changes and resource anomalies as hypotheses, not automatic causes. Inspect representative requests and dependency stages, and retain uncertainty where telemetry coverage is missing.',
['Separate successful and failed request latency.', 'Traffic changes affect error ratios and percentile interpretation.', 'Saturation includes pools, queues, disks and concurrency budgets, not just CPU.', 'Correlation suggests investigation; it does not prove causation.'],
['A single CPU metric cannot establish the root cause.', 'Temporary recovery after restart does not complete diagnosis.'],
[['Where can diagnosis start without business metrics?', 'Use ingress logs, load-balancer metrics and user reports to establish impact, then add minimal request, error and latency coverage. Mark missing data explicitly.'], ['What does high P99 with a normal average imply?', "A subset of requests may be slow. Inspect latency distributions and sample sizes by endpoint, instance, dependency and load. For Prometheus classic histograms with matching bucket boundaries, sum bucket rates across instances while retaining le, then use histogram_quantile() to estimate the aggregate P99."], ['How is a downstream failure established?', 'Correlate call errors, duration, connection-pool waits and dependency metrics. Timeouts may occur in local queues, DNS or connection setup; caller timeout messages alone do not locate the cause.'], ['Is a recent change necessarily responsible?', 'It is a useful lead. Check timing, affected objects and mechanism; even recovery after rollback needs consideration of traffic changes and supporting reproduction or comparison.'], ['What if metrics conflict with user reports?', 'Check coverage, sampling, aggregation and windows for missed cohorts or critical operations. Trace specific requests end to end instead of dismissing localized failures.']]),
'monitor/prom': card('Prometheus and federation', 'Prometheus primarily scrapes time series; metric design, label cardinality and alert semantics determine usefulness.', 'Separate collection, rule evaluation, notification and long-term storage responsibilities.',
'Design metric types and bounded labels around operational questions. Counters can reset, and fleet-level latency quantiles need appropriate aggregatable data.\n\nSeparate target discovery and scrape success from application health. Choose federation or remote write according to topology and retention, and monitor collection, backlog, deduplication and query availability independently.',
['Use counter-aware rate functions that handle resets.', 'Use appropriate histogram data for cross-instance latency aggregation.', 'Discovery identifies targets; it does not determine business health.', 'HA collection, deduplication and remote storage are separate concerns.'],
['Request IDs as labels create unbounded cardinality.', 'up=1 does not prove an exporter’s upstream system is healthy.'],
[['Pull or push?', "Long-running services normally expose metrics for Prometheus to scrape, with up reporting scrape success. Pushgateway suits service-level batch-job results, such as a periodic aggregate independent of a specific instance. It does not automatically delete pushed series, and up for the gateway does not measure reachability of the original job or instance."], ['How is cardinality controlled?', 'Estimate label-value combinations, use route templates instead of raw URLs, and put request IDs in logs or traces. Monitor active-series growth and restrict uncontrolled labels.'], ['How is long-term storage chosen?', 'Evaluate retention, queries, recovery, remote-write backlog, bandwidth, sample loss and cost. Observe delivery and query availability separately.'], ['Federation versus remote write?', 'Federation lets a higher-level Prometheus scrape selected series for hierarchical aggregation. Remote write sends samples to another endpoint. Choose from topology, query granularity and retention needs.'], ['How should alerts be routed?', 'Use service, environment, owner and severity with grouping, inhibition and silences. Test routes and provide a default receiver so alerts have responders.']]),
'monitor/slo': card('SLIs, SLOs and error budgets', 'An SLI measures service quality, an SLO sets the target, and an error budget represents the permitted bad events.', 'Verify definitions and original records before stating historical availability results.',
'Choose user-visible operations and define valid events, successful outcomes, measurement windows and exclusions. Request success, latency compliance and freshness are different possible SLIs.\n\nUse budget consumption to guide response and change risk. Preserve the original measurement contract, and distinguish a documented method from a verified personal achievement.',
['Success, latency compliance and freshness can define different SLIs.', 'Event-based and time-based budgets are not directly interchangeable.', 'Burn rate compares observed bad-event share with the allowed share.', 'Internal SLOs and external SLAs may cover different commitments.'],
['Infrastructure uptime is not automatically user-service availability.', 'Availability figures need a window, denominator and supporting evidence.'],
[['How is an SLI selected?', 'Use user-visible outcomes such as successful requests, latency compliance or data freshness. Define valid events and included errors, and verify coverage of important user paths.'], ['What if the budget is exhausted?', 'Follow an agreed policy to reduce risky changes and prioritize reliability. Repairs or risk-reducing changes may still proceed with appropriate validation; not every change must stop.'], ['How can SLO alerts avoid oversensitivity?', "For each alert tier, require both the long- and short-window error-budget burn rates to exceed the threshold. The long window captures budget impact and the short window confirms the problem is ongoing. Use different thresholds and windows for fast failures and slow degradation, and calibrate for low traffic and the intended response."], ['Should dependency failures be excluded?', 'Use the predefined commitment and measurement contract. User-facing end-to-end SLIs usually reflect dependency impact; separate attribution without changing denominators afterward to improve results.'], ['How should availability be stated in interviews?', 'Give service scope, window, source data, formula, exclusions and personal responsibility. Without records, describe the method or mark figures unverified rather than claiming a proven result.']]),
'monitor/alertfatigue': card('Reducing alert fatigue', 'An alert should call for timely action; reduce noise without hiding actual impact.', 'Evaluate actionability, missed incidents and user outcomes together.',
'Page on meaningful symptoms and use cause-oriented metrics for diagnosis. Give every alert an owner, response expectation and investigation path.\n\nReview repeated notifications and incidents, tune windows and recovery conditions, and fix recurring causes. A recovered rule only means its condition cleared; verify users, queues and side effects separately.',
['Use symptom alerts for notification and cause metrics for diagnosis.', 'Silences need scope, expiry and explanation.', 'Dependency inhibition must not hide independent incidents.', 'Automatic recovery does not prove the root cause is fixed.'],
['Raising every threshold can conceal poor alert design.', 'Not every alert merits the highest urgency.'],
[['How is alert quality measured?', 'Assess actionable notifications, duplicates, response time, missed incidents and after-hours burden with postmortems. Fewer notifications alone is not success; user impact must remain controlled.'], ['Which alerts should a new service have?', "Start with errors, latency and unavailability on critical operations, then cover actionable risks such as capacity exhaustion or backlog. For each alert, name an owner, link a diagnostic entry point such as a dashboard or runbook, and specify the expected response."], ['How is flapping handled?', 'Inspect noise, windows and thresholds, then use persistence, recovery criteria or aggregation. Simply extending every delay can postpone real incident response.'], ['How can on-call workload be reduced?', 'Identify major noise sources and recurring failures, repair frequent causes and improve handoffs and automation. Rotation changes distribute burden but do not repair reliability.'], ['What follows alert recovery?', 'Verify user metrics and critical functionality, then queues, retries and data consistency. Record the response; cleared alerts do not prove every consequence is resolved.']]),
'log/elk': card('Log platforms / ILM', 'Log platforms need reliable ingestion, deliberate mappings, lifecycle policies and controlled query access.', 'Provide separate evidence for capacity, indexing and access isolation.',
'Choose mappings for full-text search versus exact filtering, keep field growth bounded and size shards from measured ingestion, queries and recovery.\n\nCoordinate retention and storage tiers with restore requirements. Preserve audit events under an appropriate policy and enforce tenant access on the server, not just in the interface.',
['Full-text and exact-match fields need suitable mappings.', 'Unbounded dynamic fields can cause mapping explosion.', 'Shards have fixed overhead; more is not always better.', 'Lifecycle policies must align with retention and snapshot recovery.'],
['Do not flatten arbitrary business objects into unlimited dynamic fields.', 'Include replicas, queries and migration in storage-cost analysis.'],
[['How are hot and cold tiers designed?', 'Use query frequency, latency and retention requirements, checking version and deployment support. Cold data must remain recoverable; successful migration is not successful backup.'], ['How is mapping explosion addressed?', "Identify producers of uncontrolled dynamic fields, constrain dynamic mappings and normalize field structure. Elasticsearch’s flattened type maps an object with many unpredictable keys as one field and supports basic queries. Deleting documents does not shrink an existing mapping. Create an index with the new mapping and reindex the data."], ['How are shards planned?', 'Benchmark data size, growth, ingestion, concurrent queries and node resources. Use rollover to avoid excessive tiny shards or shards too large for timely recovery.'], ['How can logging costs fall?', 'Remove duplicate and low-value output, tune retention and tiers, then optimize fields and compression. Keep mandatory security/audit records under separate retention and sampling policies.'], ['How is query access isolated?', 'Enforce tenant and index scope server-side with least-privilege identities and audit records. Hiding index names in the UI or accepting arbitrary user queries is insufficient.']]),
'log/structured': card('Structured logging', 'Stable event fields support reliable search, correlation and redaction.', 'Explain schema consistency, context correlation and sensitive-data controls.',
'Define language-independent field names, types and evolution rules. Record useful events with appropriate severity and correlate them with request or trace context.\n\nMinimize sensitive payloads and observe logging failures and dropped buffers. Logging volume is not observability; audit records need stronger completeness and access controls than sampled diagnostics.',
['Keep field names and types stable with compatible evolution.', 'Levels should reflect event meaning and required action.', 'Minimize and redact payloads, tokens and personal information.', 'Observe logging failures and buffered-event drops.'],
['More log entries do not automatically improve observability.', 'Mandatory audit events should not use ordinary debug sampling.'],
[['Can logs replace APM or tracing?', 'Logs describe events, traces organize cross-service relationships and timing, and metrics summarize trends. They can correlate, but log entries alone do not guarantee a complete call tree or coverage.'], ['How should logs be sampled?', 'Choose policies by event value, traffic and incident needs, preserving important errors and context. Mandatory audit operations require an independent completeness policy.'], ['How are fields standardized across languages?', 'Define a language-neutral schema, provide language adapters and validate examples and types. A shared schema does not require one logging library everywhere.'], ['How do business and audit logs differ?', 'Audit records emphasize actor, time, object, action and outcome, with integrity, access and retention requirements. Ordinary diagnostic logs do not automatically satisfy them.'], ['What if log volume suddenly grows?', 'Break down by service, version, event and level; investigate error loops and retries. Temporarily limit low-value output, fix the cause and monitor critical-event loss.']]),
'log/trace': card('Distributed tracing', 'Context propagation connects spans; sampled traces represent only retained requests.', 'Cover synchronous and asynchronous boundaries and explain sampling limits.',
'Propagate standard context across services and messages, and model queue wait, processing and retries distinctly. Use span links when batches or multiple causes do not fit one parent chain.\n\nConnect logs through trace and span IDs while keeping metrics for aggregate rates. Choose sampling from cost and diagnostic needs, and avoid storing secrets or unnecessary personal data.',
['Parent relationships model direct calls; links can represent asynchronous or batch causality.', 'Context propagation and sampling are separate responsibilities.', 'Keep credentials and sensitive business data out of attributes.', 'Model queue wait, processing and retries separately.'],
['HTTP-only instrumentation misses messaging and background work.', 'Sampled trace counts are not complete request statistics.'],
[['How can logs link to traces?', "Read the trace ID and span ID from the active span context, put them in the log record, and use the trace backend’s expected field formats and link templates. A log can still contain IDs for a trace that sampling did not retain."], ['How is context carried through queues?', 'Inject and extract standard context in message properties, distinguishing produce, receive and process operations. Links can model batches, retries or multiple sources more accurately than a forced single parent.'], ['Head or tail sampling?', 'Head sampling decides early with predictable cost but lacks final outcomes. Tail sampling can select errors or slow traces but requires buffering, aggregation and capacity. State actual coverage and drop behavior.'], ['What do metrics and traces answer?', 'Metrics show aggregate anomalies and trends; traces explain particular paths and timing. Move from an anomalous metric to representative traces and related logs.'], ['Which attributes should be excluded?', 'Tokens, passwords, complete sensitive bodies and unnecessary personal data. Bound attribute count and size and redact before collection, even when the backend supports high cardinality.']]),
'ops/platform': card('Platform engineering', 'A platform turns repeated engineering work into self-service capabilities with explicit ownership and verifiable outcomes.', 'Explain the user workflow, operational responsibilities and evidence for adoption.',
'Start with a repeated user problem and provide a stable interface, sensible defaults and controlled extension points. Self-service still requires authorization, quotas, audit records and clear failure handling.\n\nDefine what the platform owns and what application teams own. Prioritize improvements from actual use, support requests and measurable delivery friction; a graphical wrapper around a script is not sufficient evidence of platform maturity.',
['Combine self-service with authorization, quotas and auditability.', 'Provide understandable defaults and controlled extension points.', 'Define ownership between platform and application teams.', 'Use real usage and feedback to prioritize improvements.'],
['A user interface alone does not establish a managed platform capability.', 'Forcing every business into the same implementation can hide necessary differences.'],
[['How does a platform differ from a script?', 'A platform provides stable interfaces, identity, permissions, state management, failure handling and lifecycle ownership. A small, stable requirement may be better served by a well-maintained script.'], ['How do you encourage adoption?', 'Pilot a frequent, measurable problem, reduce integration cost and provide documentation and feedback channels. Track completion rates, lead time and support load rather than relying on mandatory adoption.'], ['What should a multi-cloud platform unify?', 'Common identity, workflows and metadata where useful. Preserve provider capability differences, limits and failure states instead of claiming every service is interchangeable.'], ['How is platform reliability designed?', 'Define service objectives and dependency impact, separate control from execution, persist workflow state and make retries idempotent. Provide auditable recovery or an alternative operating path.'], ['What does CMDB integration provide?', 'Governed resource identity, ownership and relationships. Define sources, freshness, conflict resolution and reconciliation; storing records in a table does not ensure they are accurate.']]),
'ops/terraform': card('Terraform state / locking', 'Terraform plans resource changes from configuration and state; safe operation also requires checking actual resources and concurrent changes.', 'Use evidence for state recovery, drift handling and module upgrades.',
'State maps resource addresses to remote objects and may contain sensitive values. Protect both state and saved plans with access control, encryption and controlled credentials.\n\nLocking depends on the backend and configuration. Investigate the owner and running operation before removing a lock. Review drift and address changes explicitly, because a configuration refactor can otherwise propose unintended replacement.',
['State maps resource addresses to remote objects and can contain secrets.', 'Lock support and configuration depend on the backend.', 'Conditions can change between planning and applying.', 'Resource renames may require explicit address migration.'],
['Do not immediately force-unlock a state without checking the active operation.', 'Marking a value sensitive primarily controls display; it does not automatically remove it from state.'],
[['How should a stuck state lock be handled?', 'Identify the lock owner and execution, and check whether remote changes are still running. Remove a confirmed stale lock only with a recovery plan and no competing apply.'], ['How do you handle drift?', 'Compare configuration, state and actual resources, establish the intended result, then update configuration, import or apply as appropriate. Do not blindly overwrite an emergency production change.'], ["How should Terraform secrets be protected?", "Restrict access to state and plan files, encrypt storage, use short-lived credentials and keep secrets out of configuration and logs. Terraform’s sensitive marker redacts normal output, but the value can still be stored in plans and state. Where the version, provider and configuration context support it, use ephemeral values or write-only arguments to avoid persistence."], ['How do Terraform and GitOps coexist?', 'Assign infrastructure lifecycle to Terraform and application reconciliation to the GitOps controller where appropriate. Give each resource one clear owner to prevent competing changes.'], ['How are modules safely refactored?', 'Use moved blocks or a controlled state migration when addresses change. Review replacement operations and test upgrade paths; moving files alone does not guarantee unchanged resource identity.']],
{scope: 'Terraform 1.10 adds use_lockfile to the S3 backend; it is off by default. DynamoDB locking is deprecated. During migration, configure both mechanisms so updated clients acquire both locks. Retire the old lock only after every writer uses the S3 lock.'}),
'ops/gitops': card('GitOps / push-based delivery', 'GitOps continuously reconciles actual resources against declared desired state under an explicit policy.', 'Explain reconciliation, deployment policy and migration boundaries.',
'A GitOps controller observes desired state and repeatedly reconciles managed resources. Define one owner for each resource, permissions, deletion policy and the treatment of manual changes.\n\nSuccessful synchronization, resource health and business correctness are separate checks. Restoring a previous Git revision can restore compatible declarations, but it does not automatically reverse database migrations or external side effects.',
['Continuous reconciliation differs from a single deployment command.', 'Give each resource one clear owner.', 'Synchronization, health and business correctness are separate outcomes.', 'Define deletion and manual-change policies.'],
['Reverting Git does not reverse every deployment side effect.', 'Do not store plaintext production credentials in Git.'],
[['Which workloads suit GitOps?', 'Resources with declarative APIs and observable desired state fit well. One-shot operations, non-idempotent actions and systems without stable APIs need explicit lifecycle and recovery design.'], ['When is push-based delivery appropriate?', 'A simple environment or one without a resident controller may use push-based delivery. It still needs scoped identity, audit records, concurrency control and explicit rollback limits.'], ['How are secrets managed?', 'Use an external secret manager or controlled decryption, with a threat model, minimal controller permissions and rotation. Encrypted files in Git still require secure keys and access controls.'], ['How does rollback work?', 'Restore a verified artifact and compatible desired configuration, then check synchronization and business behavior. Irreversible data changes require a separate compatibility and recovery strategy.'], ['How does Helm fit?', "Argo CD uses Helm to render manifests from charts, then owns application sync and lifecycle. In a standalone Helm deployment, Helm manages the release. Define deployment ownership so both tools do not independently change the same resources."]]),
'cmdb/idem': card('Idempotency', 'Repeating one logical operation must preserve its intended business effect, not merely return a successful response.', 'Establish operation identity, atomicity and evidence from concurrent retries.',
'Bind an idempotency key to a tenant, operation type and request parameters. Store in-progress, completed and failed outcomes with defined replay behavior and retention. Concurrency control must make deduplication and the business commit consistent.\n\nFor an external operation without idempotency support, a timeout can leave the result unknown. Persist intent, query outcomes where possible and reconcile unresolved effects rather than claiming exactly-once execution.',
['Bind keys to the tenant, operation and parameters.', 'Coordinate duplicate detection and business commits under concurrency.', 'Define in-progress, completed and failed replay behavior.', 'Match retention to the possible retry window.'],
['Checking before inserting is not concurrency-safe without an atomic constraint or protocol.', 'Deduplicating messages does not automatically deduplicate external side effects.'],
[['What if an external API is not idempotent?', 'Local deduplication cannot guarantee exactly-once external effects. Persist intent and results, query uncertain outcomes and provide reconciliation or manual resolution with an explicit risk boundary.'], ['How is an idempotency key chosen?', 'Use a stable logical operation ID scoped by tenant and operation type, with parameter validation or a hash. Retries reuse the key; a new operation needs a new identity.'], ['How are deduplication and writes coordinated?', 'Within one database, use a transaction and a unique constraint where applicable. Across systems, use an outbox or durable workflow with reconciliation rather than assuming one atomic commit.'], ["How does HTTP method idempotency differ from business idempotency?", "An HTTP method is idempotent when repeated identical requests have the same intended effect on the server as a single request. Response status and body can differ. Business operations still need a defined identity and side-effect policy. An explicit idempotency protocol can make POST safe to retry under that protocol."], ['How is idempotency tested?', 'Exercise concurrent duplicates, timeout retries, crashes, conflicting payloads, expiry and unknown external results. Assert final business state and side-effect counts, not only HTTP status codes.']]),
'cmdb/lease': card('Leases / fencing', 'A lease limits ownership in time; resource-enforced fencing prevents stale owners from committing protected writes.', 'Verify that the protected resource atomically checks fencing tokens.',
'A lease holder can pause or lose connectivity and continue executing after another owner takes over. Renewal failure should stop new work, but it cannot reliably cancel every operation already in flight.\n\nIssue ordered fencing tokens through a suitable coordination mechanism and have the resource atomically reject stale writes. A random lock-owner value helps release the correct lock; it is not an ordered fencing token.',
['Random owner IDs and ordered fencing tokens serve different purposes.', 'Stopping new work does not undo operations already in flight.', 'Token issuance requires a consistent ordering mechanism.', 'Validate the token atomically with the protected write.'],
['A random Redis lock value is not a fencing token.', 'Checking a lease in the client before an unconditional write leaves a race.'],
[['What are the limits of a Redis lock?', 'Safety depends on the deployment and protocol assumptions, including replication, pauses and network failures. If stale writes are harmful, require resource-side fencing or an appropriately consistent coordination protocol.'], ['Where should fencing tokens be stored and checked?', "A coordination mechanism issues tokens in a reliable order. The protected resource tracks the highest accepted token, compares and updates it atomically with the write, and rejects lower tokens and writes that bypass the protocol. Client-local increments do not establish a common order."], ['How does clock drift affect lease safety?', 'Time-based lease decisions are affected by clock behavior, process pauses and network delay. Use the server-side lease protocol and monotonic time for local elapsed-time measurements, with fencing to reject stale writes. Clock synchronization alone does not make a lease safe.'], ['How should multiple instances compete for tasks?', 'Use atomic claiming or a coordination service to assign ownership and a version. Define timeouts, renewal, reclamation and idempotency. A reclaimed task may briefly overlap with an old worker, so final writes still require conditional protection.'], ['What happens after lease loss?', "Stop taking new work, cancel what can be cancelled and preserve state for reconciliation. The new holder takes over with a higher token, and the protected resource rejects stale writes. External systems that lack fencing still need explicit handling of uncertain side effects."]]),
'cmdb/saga': card('Workflow compensation / Saga', 'A Saga coordinates durable local transactions with compensation or forward recovery across services.', 'Explain the state machine, failure paths and business invariants.',
'Persist each workflow transition so execution can recover after a restart. Handle duplicate and out-of-order messages and distinguish failure from an unknown outcome. A Saga does not provide the isolation of one cross-service database transaction.\n\nCompensation is a business action that can also fail and may not restore the original world. Make it retryable and idempotent where possible, and define forward recovery or manual intervention for irreversible steps.',
['A Saga does not provide cross-service database isolation.', 'Compensation needs its own retry and idempotency design.', 'Persist progress so execution can resume after restart.', 'Handle duplicates, ordering and unknown outcomes explicitly.'],
['Compensation cannot automatically undo every side effect.', 'A happy-path workflow without durable recovery state is incomplete.'],
[['What if compensation fails?', 'Persist the reason and attempts, retry within a defined policy and escalate to reconciliation or manual resolution. Preserve completed-step evidence so recovery does not repeat irreversible effects.'], ['Orchestration or choreography?', 'Orchestration centralizes visibility and complex recovery. Choreography reduces central coordination but can make dependencies and diagnosis harder. Choose from workflow complexity, ownership and operational needs.'], ['How should status be presented?', 'Expose an operation ID and distinguish accepted, processing, completed, failed and attention-required states. Enqueuing a request does not mean the business operation has completed.'], ["What does a message broker solve in a saga?", "A message broker decouples components and provides durable delivery according to its configuration. Business steps still need coordinated local commits and publication, idempotent consumers and durable workflow state to handle duplicates and inconsistencies."], ['How are recovery paths tested?', 'Inject failures around each commit, duplicate deliveries, timeouts and restarts. Verify durable progress, compensation and business invariants; an empty queue alone is not evidence of correctness.']]),
'cmdb/worker': card('Precomputation workers', 'Background workers build derived read models whose freshness, duplicate handling and repair must be explicit.', 'Define the freshness objective, source of truth and rebuild or reconciliation evidence.',
'Use precomputation when repeated expensive reads justify a derived model. Keep the authoritative source clear and make the read model rebuildable. Account for duplicate, delayed, out-of-order and missing events through version checks and reconciliation.\n\nMeasure source-to-result delay, queue wait and execution time. Persist per-item outcomes in partial batches and scale from actual bottlenecks; more workers can overload shared databases or hot partitions.',
['Derived data must have an authoritative source and a rebuild path.', 'Use versions and reconciliation for unreliable event delivery.', 'Record partial batch outcomes per item.', 'Scale against measured bottlenecks and partitioning.'],
['A running worker does not prove its read model is fresh.', 'Retrying an entire partial batch can repeat completed side effects.'],
[['How is freshness measured?', 'Track event-to-completion delay, queue wait, execution and last update, alongside source activity. An empty queue may also mean the producer stopped.'], ['How is correctness reconciled?', 'Compare business keys, versions and aggregates between the source and read model, then rebuild bounded ranges. Report coverage and repair results; a few samples do not prove full consistency.'], ['How are partial batches retried?', 'Persist per-item outcomes and retry only safe unresolved work. Query unknown results or use idempotency and version checks rather than blindly repeating the batch.'], ['How is backlog handled?', 'Separate increased arrivals, downstream limits, hot partitions and retry amplification. Apply admission control, coalescing, measured scaling or pauses while protecting online traffic.'], ["Does adding workers always increase throughput?", "No. Database locks, connection limits, partition counts or a single hot key can constrain parallelism. Measure throughput, tail latency and saturation to assess the benefit of adding workers, and set a concurrency limit."]]),
'report/board': card('Reporting / precomputation', 'Reliable reporting requires consistent metric definitions, traceable data versions and explicit freshness.', 'Show the complete path from metric definition and authorization to freshness and performance tests.',
'Define the business meaning, time range, time zone and deduplication rules before choosing live aggregation or precomputation. Display the reporting period and update time so similar labels do not conceal different calculations.\n\nAuthorize queries by tenant and bound time ranges, sorting and pagination cost. Validate performance against correctness and freshness objectives, including cold caches and concurrent updates.',
['Maintain each metric’s definition and source.', 'Attach update times and versions to derived results.', 'Enforce authorization in queries, cache keys and exports.', 'Define treatment of late data and corrections.'],
['Cache keys must include the tenant and relevant authorization scope.', 'Returning stale data faster is not a complete performance improvement.'],
[['How are reporting and worker responsibilities divided?', "Workers calculate and update derived results. The reporting service owns authorization, queries and the presentation contract. Both share metric definitions and versions, and the reporting service detects missing or stale results."], ['How are conflicting metrics reconciled?', 'Compare numerators, denominators, time windows, status filters and deduplication against the business definition. Matching interface labels cannot resolve different calculations.'], ['When is live calculation necessary?', 'Consider it when asynchronous updates cannot meet the freshness requirement and query cost is acceptable. Combining live increments with historical aggregates requires explicit consistency and deduplication rules.'], ['How are tenant reports isolated?', 'Derive trusted tenant scope from identity and enforce it in queries, caches, background calculations and exports. Test cross-tenant access; a client-supplied tenant parameter is not authorization.'], ['How are optimizations validated?', 'Use representative tenant sizes, query ranges and concurrency. Compare latency distributions, resource use and result consistency for cold caches, warm caches and updates.']]),
'other/nacos': card('Nacos configuration', 'Nacos provides configuration management and service discovery; clients must handle disconnection, failed updates and local state.', 'Verify the actual SDK, server version and failure policy.',
'Scope configuration by environment and application, validate syntax and semantics before publication, and maintain recoverable versions. Discovered instances still require request timeouts, load balancing and failure handling.\n\nDefine caching, reconnection and empty-configuration behavior. Test both startup and continued operation when the configuration service is unavailable, and verify authentication and authorization in the deployed version.',
['Validate updates before atomically replacing active configuration.', 'Discovering an instance does not guarantee a successful request.', 'Local snapshots improve availability but can become stale.', 'Namespaces alone do not secure sensitive configuration.'],
['Do not overwrite all active settings merely because an empty response arrives.', 'A login screen does not prove that server-side authorization is enabled.'],
[['Nacos configuration or ConfigMap?', "ConfigMap integrates with the Kubernetes resource lifecycle. Nacos publishes configuration independently and lets clients subscribe to changes. Compare update behavior, application integration, availability and operating cost, and keep a single source of truth."], ['What should happen with empty or invalid configuration?', 'Distinguish deletion, read failure and a valid empty value, then validate the schema. Retain the last valid version with an alert, or refuse startup for required configuration, according to an explicit policy.'], ['How is discovery failure investigated?', 'Check namespace, group, service name, instance health and client connectivity, then actual network and request failures. A discovered instance may still be unable to serve the request.'], ['How are configuration permissions controlled?', 'Grant minimal permissions by environment, application and operation; verify server-side enforcement and restrict network access. Separate publication and reading permissions, and control sensitive log output.'], ['How does go-zero use Nacos?', 'Check the adapter, client and versions actually used. Identify configuration loading, discovery and update integration explicitly; a framework name does not prove automatic hot reload or fallback.']]),
'other/audit': card('SQL review and audit', 'A SQL platform constrains permissions and execution risks and preserves the audit trail from request to outcome.', 'Explain responsibilities across authorization, review, execution and audit.',
'Separate user identity, data-source authorization, review rules, approval and execution credentials. Syntax checks cover only part of the risk; assess affected rows, locks, scans, resource demand and recovery before execution.\n\nBound execution time and resources, and record actor, approval, SQL fingerprint, target database and result. Sensitive result display and export require their own authorization and redaction.',
['Enforce tenant authorization in both query and execution paths.', 'Read-only SQL can still exhaust resources or disclose data.', 'A timeout can leave an unknown result that needs verification.', 'Ordinary execution identities should not be able to alter audit records.'],
['Syntax validation is not a complete safety review.', 'Do not execute every user request with one shared administrator identity.'],
[['How do platform and database permissions interact?', 'The platform authorizes requested operations; the database identity supplies the final permission boundary. Keep them consistent and auditable rather than giving an unrestricted execution account behind a restricted page.'], ['How is risky SQL identified?', 'Combine statement type, object scope, predicates, execution plans and resource estimates, with human review for high-risk operations. Rules have false positives and false negatives and cannot identify every risk.'], ['How are long queries controlled?', 'Bound duration, concurrency and result size, inspect plans and indexes, and consider replicas or offline jobs. Ending a client wait may not stop database execution; verify cancellation.'], ['What belongs in an audit record?', 'Record the actor, time, target, approval, operation summary, execution identity and result as required. Protect sensitive fields, define retention, and consider failed or denied operations too.'], ["How is tenant isolation enforced in a Django REST Framework application?", "Establish trusted tenant context after authentication and scope querysets, object access, background tasks and exports to it. DRF object permissions do not check each item in list responses or automatically constrain creates. Filter lists explicitly, validate tenant ownership on creation and test cross-tenant access."]]),
'other/backup': card('Backup and recovery', 'A successful backup job creates backup data; recovery capability requires integrity checks and restore exercises.', 'Distinguish job completion, backup integrity and verified business recovery.',
'Define recovery point and recovery time objectives from business needs. Select backup frequency, incremental chains, log archives and isolated storage, including critical configuration, keys and version information needed for restoration.\n\nRestore in an isolated environment and verify data, dependencies, application startup and critical workflows. A checksum establishes byte integrity, not business consistency or recoverability. Record actual recovery time and remaining gaps; a successful job alone does not establish recovery capability.',
['RPO bounds acceptable data loss; RTO targets recovery time.', 'An incremental restore requires a complete and usable backup chain.', 'Replication and high availability do not replace isolated, recoverable backups.', 'Credentials and encryption keys must remain recoverable independently of the failed system.'],
['A successful exit status without a restore exercise does not establish recoverability.', 'Copies in the same account with the same access and deletion permissions may share the same failure exposure.'],
[['How does a scheduled Go job fit into a backup system?', 'Go can orchestrate backup commands, upload artifacts and verify checksums. Consistent database backups still depend on the database protocol and backup tool; invoking a script does not establish backup consistency.'], ['How are RPO and RTO determined?', 'Start with acceptable business data loss and recovery time, then choose backup frequency, log archives and recovery architecture. Measure restoration against both objectives; a configured schedule alone does not prove they are met.'], ['What should a restore exercise verify?', 'Check backup chains, version compatibility, keys, data consistency, application startup and critical workflows. Record elapsed time and gaps; decompressing a file is not a complete recovery.'], ['How is a failed backup handled?', 'Identify source, capacity, network, permission or verification failures, assess the most recent recoverable point against the objective, then alert and retry or use an alternative. Do not overwrite the last usable backup with repeated failures.'], ['How should cloud backups be isolated?', 'Choose cross-account, cross-region, immutable retention or offline copies from the threat model and recovery objective. Restrict deletion and protect credentials independently; replication can also propagate destructive changes.']]),
'other/secrets': card('Secrets management', 'Secrets management covers generation, authorization, delivery, rotation, revocation and audit, not just encrypted storage.', 'Explain minimal permissions and verifiable credential rotation.',
'Prefer workload identities and short-lived credentials, scoped by service and environment. Keep credentials out of source code, images, logs and uncontrolled build caches, and restrict runtime access.\n\nRotation requires a transition between credentials, renewed connections and verification that consumers switched. After exposure, revoke or rotate active credentials first, then remove exposed copies and investigate their use.',
['Encrypted storage still needs protected decryption keys and permissions.', 'Environment variables, files and APIs have different exposure paths.', 'Base64 encoding a Kubernetes Secret is not encryption.', 'Long-lived credentials need owners, purposes and expiry management.'],
['Deleting a secret from Git does not revoke copies already obtained.', 'Updating the stored secret does not prove that consumers rotated.'],
[['What if a secret was committed to Git?', 'Immediately revoke or rotate active credentials and investigate access and usage. Clean history and caches as appropriate; rewriting history cannot recover copied credentials.'], ['What does Vault provide?', 'It can provide controlled secret access, dynamic credentials, leases and audit. Authentication, policies, availability, recovery and application integration still need design and verification.'], ['How are Kubernetes Secrets protected?', 'Use appropriate encryption at rest, RBAC and namespace boundaries, restrict workload access, and control logs and dumps. Permissions such as creating Pods can allow indirect secret access and need assessment.'], ['How can rotation avoid downtime?', "Use an overlap period where supported, update consumers and verify that new connections use the new credential before revoking the old one. If the system cannot support overlapping credentials or hot reload, plan a controlled restart and rollback."], ['What should secret access auditing capture?', 'Record who accessed, updated or revoked which credential, when and with what outcome. Monitor unusual sources and rates, omit plaintext secrets and independently protect the audit log.']]),
'other/oncall': card('Incident response / on-call', 'Incident response controls user impact, establishes shared facts, restores service and tracks improvements.', 'Use a timeline, evidence and accepted improvements to explain personal contributions.',
'Classify severity by impact and urgency, and assign coordination, technical response and communication roles. Record hypotheses, actions and outcomes, prioritizing verifiable and reversible mitigation.\n\nAfter recovery, check backlog, data and dependencies. Review the system conditions that allowed the incident to grow, and assign owners and acceptance criteria to improvements instead of only asking people to be more careful.',
['Severity reflects business impact, not the number of component alerts.', 'Separate confirmed facts, hypotheses and the next update time.', 'Mitigation and root-cause repair may happen in separate stages.', 'Postmortems examine how system conditions amplified the failure.'],
['Uncoordinated simultaneous changes make incident response harder.', 'Temporary availability does not prove that all data and business effects are resolved.'],
[['How are severity levels defined?', "Base severity on critical user journeys, scope, duration, data risk and the availability of workarounds. Update it as facts change, with clear response and communication expectations for each level."], ['How should responders communicate?', 'State current impact, confirmed facts, actions underway and the next update time. Avoid unsupported recovery promises or presenting unverified hypotheses as the root cause.'], ['What should a postmortem produce?', 'A verifiable timeline, triggering and amplifying mechanisms, detection and response gaps, and improvements with acceptance criteria. Separate triggers from systemic conditions rather than assigning personal blame.'], ['How are frequent nighttime alerts reduced?', 'Analyze repeated symptoms and actionable value, repair frequent causes and routing, and improve recovery automation and runbooks. Check missed incidents and user impact as well as notification volume.'], ['How are changes controlled during an incident?', 'Coordinate changes centrally and record purpose, expected effect and rollback conditions. Pause unrelated releases when needed and verify after each intervention to preserve causal evidence.']]),
'other/capacity': card('Capacity planning', 'Capacity planning connects business demand, resource bottlenecks and service objectives through representative load tests.', 'Report improvements only with a baseline, a defined measure and verification records.',
'Model request volume, data size, tenant distribution and peaks. Measure throughput, tail latency, errors and saturation across load levels. Usable capacity is the load that meets service objectives, not the point at which a machine finally stops accepting requests.\n\nAllow for failure, growth, startup delay and dependency limits. Compare cost changes alongside performance, reliability and operating complexity so an apparent saving does not simply move the bottleneck elsewhere.',
['Include hot keys, long requests and read/write ratios in the load model.', 'State test environment, data size and dependency conditions.', 'Partitions, locks, quotas and shared dependencies constrain scaling.', 'Reserve capacity for failures and scaling delay.'],
['Uniform tests on tiny datasets do not predict production peaks.', 'Average CPU alone does not establish available capacity.'],
[['What makes a load test credible?', 'Use representative request distributions, data and dependencies, increase load gradually and record latency distributions, errors and resources. Distinguish generator limits from system limits and preserve reproducible configuration and results.'], ['How are traffic bursts handled?', 'Combine reserves, rate limiting, bounded queues, degradation and elastic scaling with startup times and downstream quotas. Queues buffer finite bursts; they cannot absorb sustained input above processing capacity.'], ['How are cost savings measured?', 'Compare total cost at equivalent business volume, service objectives and time periods, explaining price, resource and traffic changes. Resource-count reductions alone do not prove financial savings.'], ['How is tenant capacity isolated?', 'Apply concurrency, request, storage and background-job quotas, identify hot tenants and test fairness. Observe shared databases and caches separately because interference can remain.'], ['What if the database is the bottleneck?', 'Investigate queries, indexes, locks, connections, I/O and data skew before choosing caching, batching, read replicas or sharding. Base architectural changes on measurements.']]),
};
